    const auto& catalog = catalog_reloader_->catalog();
    if (!m.pickup_station.empty()) {
      from_st = amr_dispatcher_core::catalog::FindStation(catalog, m.pickup_station);
    }
    if (!m.dropoff_station.empty()) {
